#!/usr/bin/env bash
# Step R4.3 rehearsal (no cloud, seconds): the job is made reproducible (two builds that differ only by build-time stamps become byte-identical, a signed jar keeps its content, every fault is refused), and the
# JDK cache is removed only when the JVM works without it.
#   bash r4d-rehearse.sh KITDIR
set -uo pipefail
K="$(cd "${1:?usage: $0 KITDIR}" && pwd)"; B="$K/ops/image/build"; W="$(mktemp -d)"; trap 'rm -rf "$W"' EXIT; P=0; F=0
chk() { if [ "$2" = ok ]; then echo "   ok:   $1"; P=$((P+1)); else echo "   FAIL: $1"; F=$((F+1)); fi; }
say() { echo; echo "== $*"; }
say "two fake builds of the same job that differ only by build-time stamps (as the experiment found)"
python3 -B - "$W" <<'PYEOF'
import io, sys, zipfile
W = sys.argv[1]
def jar(entries, ts, extra=b"", compress=zipfile.ZIP_DEFLATED, attr0=False):
    b = io.BytesIO(); z = zipfile.ZipFile(b, "w")
    for name, body in entries:
        zi = zipfile.ZipInfo(name, ts); zi.compress_type = compress; zi.extra = extra; zi.external_attr = 0 if attr0 else ((0o755 << 16) if name.endswith("/") else (0o644 << 16))
        z.writestr(zi, body); zi.external_attr = 0 if attr0 else zi.external_attr
    z.close(); return b.getvalue()
def job(path, comment, ts, extra):
    own = jar([("META-INF/MANIFEST.MF", b"Manifest-Version: 1.0\n"), ("META-INF/maven/org.x/own/pom.properties", ("#Generated by Maven\n#%s\nversion=0.1\n" % comment).encode()), ("a/B.class", b"\xca\xfe\xba\xbe-own")], ts, extra, attr0=True)
    signed = jar([("META-INF/MANIFEST.MF", b"Manifest-Version: 1.0\nName: a/S.class\nSHA-256-Digest: abc\n"), ("META-INF/SIG.SF", b"Signature-Version: 1.0\n"), ("META-INF/SIG.RSA", b"\x30\x82-rsa"), ("META-INF/maven/org.y/signed/pom.properties", b"#Tue Jan 01 00:00:00 UTC 2019\nversion=9\n"), ("a/S.class", b"\xca\xfe\xba\xbe-signed")], ts, extra, attr0=True)
    outer = [("META-INF/MANIFEST.MF", b"Manifest-Version: 1.0\nMain-Class: x\n"), ("classes/", b""), ("classes/c.txt", b"text\n"), ("lib/", b""), ("lib/own.jar", own), ("lib/signed.jar", signed), ("nutch-default.xml", b"<configuration/>\n")]
    b = io.BytesIO(); z = zipfile.ZipFile(b, "w")
    for name, body in outer:
        zi = zipfile.ZipInfo(name, ts); zi.extra = extra; zi.external_attr = (0o755 << 16) if name.endswith("/") else (0o644 << 16)
        zi.compress_type = zipfile.ZIP_STORED if name == "lib/signed.jar" else zipfile.ZIP_DEFLATED
        z.writestr(zi, body)
    z.close(); open(path, "wb").write(b.getvalue())
job(W + "/A.job", "Mon Oct 26 15:01:49 UTC 2026", (2026, 10, 26, 15, 8, 48), b"")
job(W + "/B.job", "Mon Oct 26 17:44:24 UTC 2026", (2026, 10, 26, 17, 51, 54), b"UT\x05\x00\x01\x00\x00\x00\x00")
PYEOF
[ "$(sha256sum < "$W/A.job")" != "$(sha256sum < "$W/B.job")" ] && chk "the two fake builds differ (the problem exists: another stamp, other header times, other extra fields)" ok || chk "the fake builds are equal: the test would prove nothing" no
for n in A B; do python3 "$B/tc-job-normalize.py" "$W/$n.job" "$W/$n.norm" > "$W/$n.out" 2>&1 || chk "normalizing $n failed: $(cat $W/$n.out)" no; done
[ "$(sha256sum < "$W/A.norm")" = "$(sha256sum < "$W/B.norm")" ] && chk "after the normalization the two builds are BYTE-IDENTICAL" ok || chk "the two builds still differ after the normalization" no
grep -q '^JOB-NORMALIZED: 15 entries, 2 nested jars, 1 date lines removed from pom.properties, 1 signed jar(s) left unchanged in content' "$W/A.out" && chk "the report: 15 entries (7 outer, 8 inside the nested jars), 2 nested jars, 1 date line removed (the unsigned jar's pom.properties), 1 signed jar left unchanged" ok || chk "the report is not as expected: $(cat $W/A.out)" no
python3 -B - "$W" <<'PYEOF' > "$W/check.txt" 2>&1
import io, sys, zipfile
W = sys.argv[1]; z0 = zipfile.ZipFile(W + "/A.job"); z1 = zipfile.ZipFile(W + "/A.norm"); ok = lambda m, c: print(("PASS " if c else "FAIL ") + m)
ok("the entries and their order are unchanged", [i.filename for i in z0.infolist()] == [i.filename for i in z1.infolist()])
ok("every header time of the outer file is 1980-01-01 00:00:00", all(i.date_time == (1980, 1, 1, 0, 0, 0) for i in z1.infolist()))
own0 = zipfile.ZipFile(io.BytesIO(z0.read("lib/own.jar"))); own1 = zipfile.ZipFile(io.BytesIO(z1.read("lib/own.jar"))); sg1 = zipfile.ZipFile(io.BytesIO(z1.read("lib/signed.jar"))); sg0 = zipfile.ZipFile(io.BytesIO(z0.read("lib/signed.jar")))
ok("every header time inside the nested jars is 1980-01-01 00:00:00", all(i.date_time == (1980, 1, 1, 0, 0, 0) for z in (own1, sg1) for i in z.infolist()))
p = own1.read("META-INF/maven/org.x/own/pom.properties")
ok("the unsigned jar's pom.properties lost the date line and kept the rest", b"#Mon" not in p and b"version=0.1" in p and b"#Generated by Maven" in p)
ok("the SIGNED jar's content is unchanged, including its pom.properties with the date line (a changed signed jar would fail its signature)", all(sg0.read(i.filename) == sg1.read(i.filename) for i in sg0.infolist()) and b"#Tue Jan 01" in sg1.read("META-INF/maven/org.y/signed/pom.properties"))
ok("class files, text and the manifest are byte for byte unchanged", own0.read("a/B.class") == own1.read("a/B.class") and z0.read("nutch-default.xml") == z1.read("nutch-default.xml") and z0.read("META-INF/MANIFEST.MF") == z1.read("META-INF/MANIFEST.MF"))
ok("permissions are kept in the outer file (0644 on files, 0755 on directories)", {i.filename: i.external_attr for i in z0.infolist()} == {i.filename: i.external_attr for i in z1.infolist()})
ok("a permission field of 0, as Java-made jars have it, stays 0 inside the nested jars (Python writes 0o600 for a 0 unless it is put back)", {i.filename: i.external_attr for i in own0.infolist()} == {i.filename: i.external_attr for i in own1.infolist()} and {i.filename: i.external_attr for i in sg0.infolist()} == {i.filename: i.external_attr for i in sg1.infolist()} and all(i.external_attr == 0 for i in own1.infolist()))
ok("the stored entry stays stored, the deflated stay deflated", {i.filename: i.compress_type for i in z0.infolist()} == {i.filename: i.compress_type for i in z1.infolist()})
ok("the result opens without a damaged entry", z1.testzip() is None and own1.testzip() is None and sg1.testzip() is None)
PYEOF
[ "$(grep -c '^PASS' "$W/check.txt")" = 10 ] && chk "all 10 properties of the result hold (order, times, pom.properties, signed jar untouched, content, permissions, compression, readable)" ok || chk "a property failed: $(grep FAIL "$W/check.txt" | tr '\n' '|')" no
python3 "$B/tc-job-normalize.py" "$W/A.norm" "$W/A.norm2" > /dev/null 2>&1; [ "$(sha256sum < "$W/A.norm")" = "$(sha256sum < "$W/A.norm2")" ] && chk "a second run changes nothing (the result is stable)" ok || chk "the result is not stable" no
if command -v unzip >/dev/null 2>&1; then unzip -tq "$W/A.norm" > "$W/unzip.txt" 2>&1 && chk "Info-ZIP unzip -t also accepts the result" ok || chk "unzip rejects the result: $(cat $W/unzip.txt)" no; else chk "(unzip is not installed here; the Python check above stands)" ok; fi
say "faults: each must be refused, and the input must not be touched"
sha_in="$(sha256sum < "$W/A.job")"
echo "this is not a zip" > "$W/bad.job"; python3 "$B/tc-job-normalize.py" "$W/bad.job" "$W/bad.out" > "$W/o.txt" 2>&1; [ $? = 1 ] && grep -q 'is not a zip or jar file' "$W/o.txt" && [ ! -e "$W/bad.out" ] && chk "fault: a file that is not a zip is refused and nothing is written" ok || chk "non-zip not refused" no
head -c 700 "$W/A.job" > "$W/trunc.job"; python3 "$B/tc-job-normalize.py" "$W/trunc.job" "$W/trunc.out" > "$W/o.txt" 2>&1; [ $? = 1 ] && [ ! -e "$W/trunc.out" ] && chk "fault: a truncated job is refused and nothing is written" ok || chk "truncated job not refused: $(cat $W/o.txt | head -2)" no
python3 "$B/tc-job-normalize.py" "$W/A.job" "$W/e.out" --epoch 1970-01-01 > "$W/o.txt" 2>&1; [ $? = 1 ] && grep -q 'before 1980' "$W/o.txt" && chk "fault: an epoch before 1980 is refused (a zip cannot hold it)" ok || chk "bad epoch not refused" no
python3 "$B/tc-job-normalize.py" "$W/A.job" "$W/f.out" --epoch 2026-13-40 > "$W/o.txt" 2>&1; python3 "$B/tc-job-normalize.py" "$W/A.job" "$W/g.out" --epoch notadate > "$W/o2.txt" 2>&1; [ $? = 1 ] && grep -q 'YYYY-MM-DD' "$W/o2.txt" && chk "fault: an epoch that is not a date is refused" ok || chk "garbage epoch not refused" no
python3 "$B/tc-job-normalize.py" "$W/nonexistent.job" "$W/h.out" > "$W/o.txt" 2>&1; [ $? = 1 ] && grep -q 'cannot read' "$W/o.txt" && chk "fault: a missing input is refused with a message" ok || chk "missing input not refused" no
[ "$(sha256sum < "$W/A.job")" = "$sha_in" ] && chk "the input file was never modified" ok || chk "the input changed" no
say "the tool's own safety net: it refuses a result that is not the same job"
python3 -B - "$B" "$W" > "$W/net.txt" 2>&1 <<'PYEOF2'
import importlib.util, io, sys, zipfile
spec = importlib.util.spec_from_file_location("n", sys.argv[1] + "/tc-job-normalize.py"); n = importlib.util.module_from_spec(spec); spec.loader.exec_module(n)
W = sys.argv[2]; orig = open(W + "/A.job", "rb").read(); good = open(W + "/A.norm", "rb").read(); ok = lambda m, c: print(("PASS " if c else "FAIL ") + m)
ok("the correct result has no problems", n.problems(orig, good, 0) == [])
def rewrite(mutate):
    zin = zipfile.ZipFile(io.BytesIO(good)); out = io.BytesIO(); z = zipfile.ZipFile(out, "w")
    for i in mutate(zin.infolist(), zin):
        zi = zipfile.ZipInfo(i[0], (1980, 1, 1, 0, 0, 0)); zi.external_attr = i[2]; zi.compress_type = zipfile.ZIP_DEFLATED; z.writestr(zi, i[1])
    z.close(); return out.getvalue()
base = lambda infos, zin: [(i.filename, zin.read(i), i.external_attr) for i in infos]
ok("a changed text file is detected", n.problems(orig, rewrite(lambda infos, zin: [(a, b"CHANGED" if a == "nutch-default.xml" else b, c) for a, b, c in base(infos, zin)]), 0) != [])
ok("a missing entry is detected", n.problems(orig, rewrite(lambda infos, zin: base(infos, zin)[:-1]), 0) != [])
ok("a reordered entry is detected", n.problems(orig, rewrite(lambda infos, zin: list(reversed(base(infos, zin)))), 0) != [])
ok("a changed permission is detected", n.problems(orig, rewrite(lambda infos, zin: [(a, b, 0 if a == "classes/c.txt" else c) for a, b, c in base(infos, zin)]), 0) != [])
PYEOF2
[ "$(grep -c '^PASS' "$W/net.txt")" = 5 ] && chk "the verifier accepts the correct result and detects a changed file, a missing entry, a reordered entry and a changed permission" ok || chk "the verifier is wrong: $(grep FAIL "$W/net.txt" | tr '\n' '|')" no
sed 's/zi = zipfile.ZipInfo(i.filename, epoch)/body = body + b"x" if i.filename.endswith(".class") else body; zi = zipfile.ZipInfo(i.filename, epoch)/' "$B/tc-job-normalize.py" > "$W/buggy.py"
python3 -B "$W/buggy.py" "$W/A.job" "$W/buggy.out" > "$W/o.txt" 2>&1; [ $? = 1 ] && grep -q 'is not the same job' "$W/o.txt" && [ ! -e "$W/buggy.out" ] && chk "a copy of the tool with a bug that corrupts class files REFUSES to write its result (it checks itself before it writes)" ok || chk "the self-check did not stop a corrupting bug: $(head -c 200 $W/o.txt)" no
say "the JDK cache script (a fake JDK)"
mkjdk() { rm -rf "$W/jdk"; mkdir -p "$W/jdk/bin" "$W/jdk/lib/server"; printf '#!/bin/sh\nexit %s\n' "${1:-0}" > "$W/jdk/bin/java"; chmod +x "$W/jdk/bin/java"; [ "${2:-yes}" = yes ] && head -c 1000 /dev/zero > "$W/jdk/lib/server/classes.jsa"; }
mkjdk 0 yes; out="$(TC_SUDO="" bash "$B/tc-image-jdkcache.sh" "$W/jdk" 2>&1)"; [ $? = 0 ] && [ ! -e "$W/jdk/lib/server/classes.jsa" ] && grep -q 'JDKCACHE-OK: classes.jsa removed (1000 bytes)' <<<"$out" && chk "the cache is removed when the JVM works without it" ok || chk "cache not removed: $out" no
mkjdk 0 no; out="$(TC_SUDO="" bash "$B/tc-image-jdkcache.sh" "$W/jdk" 2>&1)"; [ $? = 0 ] && grep -q 'is not there' <<<"$out" && chk "an image without the cache is fine (the script can run twice)" ok || chk "absent cache not accepted: $out" no
mkjdk 3 yes; out="$(TC_SUDO="" bash "$B/tc-image-jdkcache.sh" "$W/jdk" 2>&1)"; [ $? = 1 ] && [ -e "$W/jdk/lib/server/classes.jsa" ] && grep -q 'nothing was removed' <<<"$out" && chk "fault: when the JVM does not start without the cache, NOTHING is removed" ok || chk "unsafe removal: $out" no
rm -rf "$W/jdk"; out="$(TC_SUDO="" bash "$B/tc-image-jdkcache.sh" "$W/jdk" 2>&1)"; [ $? = 1 ] && grep -q 'no java at' <<<"$out" && chk "fault: a folder with no java is refused" ok || chk "no-java not refused" no
say "two runs of the job stage at the same time (a second run deletes the first one's work folder)"
( exec 7>"$W/job.lock"; flock -x 7; sleep 6 ) &
LP=$!; sleep 1
out="$(TC_LOCK="$W/job.lock" TC_WORK="$W/jw" bash "$B/tc-image-job.sh" "$K" x y 2>&1)"; rc=$?
[ $rc = 1 ] && grep -q 'another run of this stage is active on this machine' <<<"$out" && [ ! -e "$W/jw" ] && chk "a second run while the lock is held is refused, says why, and deletes nothing" ok || chk "the job stage ran twice at once: $out" no
wait $LP 2>/dev/null
out="$(TC_LOCK="$W/job.lock" TC_WORK="$W/jw" bash "$B/tc-image-job.sh" "$K" x y 2>&1)"; rc=$?
! grep -q 'another run of this stage' <<<"$out" && grep -q 'software layer is not in place' <<<"$out" && chk "with the lock free the script gets past the lock (and stops at its own pre-flight, as it must on this fake machine)" ok || chk "the lock blocked a single run: $out" no
mkdir -p "$W/emptypath"; out="$(PATH="$W/emptypath" TC_LOCK="$W/job2.lock" TC_WORK="$W/jw2" /bin/bash "$B/tc-image-job.sh" "$K" x y 2>&1)"; rc=$?
[ $rc = 1 ] && grep -q 'flock is not installed' <<<"$out" && ! grep -q 'another run of this stage' <<<"$out" && chk "when flock is missing the script says so (it does NOT claim that another run is active)" ok || chk "a missing flock is reported wrongly: $out" no
for f in tc-image-job.sh tc-image-bake.sh; do
  miss="$(python3 -B - "$B/$f" <<'PYEOF3'
import re, subprocess, sys
src = open(sys.argv[1]).read()
# every helper that the script calls as a command at the start of a statement (say, fail, beat_on, beat_off, fp, ...) must be DEFINED in the script (a trailing comment once swallowed a definition)
defined = set(re.findall(r"(?m)(?:^|;\s*)([a-z_][a-z0-9_]*)\(\)\s*\{", src))
called = set(re.findall(r"(?m)(?:^|[;&|]\s*|\{\s*|\(\s*)(beat_on|beat_off|say|fail|fp)\b", src))
print(" ".join(sorted(called - defined)))
PYEOF3
)"
  [ -z "$miss" ] && chk "$f: every helper that it calls (say, fail, beat_on, beat_off, fp) is defined in it" ok || chk "$f calls helpers that are not defined: $miss" no
done
say "the scripts of the build call them, in the right order"
jl() { grep -n "$1" "$B/$2" | head -1 | cut -d: -f1; }
a="$(jl 'ant runtime failed' tc-image-job.sh)"; n="$(jl 'tc-job-normalize.py' tc-image-job.sh)"; f="$(jl 'JOBFACTS=' tc-image-job.sh)"; w="$(jl 'wrapper-jar.sh" build' tc-image-job.sh)"
[ -n "$a" ] && [ -n "$n" ] && [ -n "$f" ] && [ "$a" -lt "$n" ] && [ "$n" -lt "$f" ] && [ "$n" -lt "$w" ] && chk "the job is normalized after ant has succeeded and BEFORE it is counted, hashed or used for the wrapper jar" ok || chk "the order in tc-image-job.sh is wrong (ant $a, normalize $n, facts $f, wrapper $w)" no
j="$(jl 'JDK: \$JDK' tc-image-bake.sh)"; c="$(jl 'tc-image-jdkcache.sh' tc-image-bake.sh)"; [ -n "$j" ] && [ -n "$c" ] && [ "$j" -lt "$c" ] && chk "the bake removes the JDK cache right after the JDK is installed" ok || chk "the order in tc-image-bake.sh is wrong" no
echo; echo "pass: $P   fail: $F"; [ "$F" = 0 ] && echo "R4D-REHEARSAL-PASS" || { echo "R4D-REHEARSAL-FAIL"; exit 1; }
